app.innerHTML = `<button type="button" id="back">Projects</button><h1 id="project-name"></h1>
  <form id="task-form"><label>Task title<input name="title" aria-label="Task title"></label><button type="submit">Create task</button></form>
  <div id="alert" role="alert" aria-live="polite"></div>
  <label>Task filter<select id="task-filter" aria-label="Task filter"><option>All</option><option>Open</option><option>Completed</option></select></label>
  <section id="tasks" aria-label="Tasks"></section>`;
app.querySelector('#project-name').textContent = project.name;
app.querySelector('#back').addEventListener('click', () => go('/'));
const alert = app.querySelector('#alert');
const taskForm = app.querySelector('#task-form');
const filter = app.querySelector('#task-filter');
async function renderTasks() {
  const response = await fetch(`/api/projects/${project.id}/tasks`);
  if (!response.ok) throw new Error('Could not load tasks');
  const tasks = await response.json();
  const list = app.querySelector('#tasks'); list.replaceChildren();
  for (const task of tasks.filter(item => filter.value === 'All' || (filter.value === 'Completed') === Boolean(item.completed))) {
    const row = document.createElement('div'); row.className = 'task-row'; row.dataset.testid = 'task-row';
    const title = document.createElement('span'); title.textContent = task.title;
    const label = document.createElement('label');
    const checkbox = document.createElement('input'); checkbox.type = 'checkbox'; checkbox.checked = Boolean(task.completed); checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      const saved = await fetch(`/api/projects/${project.id}/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      if (!saved.ok) { checkbox.checked = !checkbox.checked; alert.textContent = 'Unable to update task'; return; }
      await renderTasks();
    });
    label.append(checkbox); row.append(title, label); list.append(row);
  }
}
filter.addEventListener('change', () => renderTasks().catch(() => { alert.textContent = 'Unable to load tasks'; }));
taskForm.addEventListener('submit', async event => {
  event.preventDefault(); const input = taskForm.elements.title; const title = input.value.trim();
  if (!title) { alert.textContent = 'Task title is required'; return; }
  const response = await fetch(`/api/projects/${project.id}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
  if (!response.ok) { alert.textContent = 'Unable to create task'; return; }
  input.value = ''; alert.textContent = ''; await renderTasks();
});
renderTasks().catch(() => { alert.textContent = 'Unable to load tasks'; });

